const h1 = document.getElementById('main-title');
const link = document.getElementById('author-link');
const btn = document.getElementById('btn-reserve');
const brand = document.getElementById('brand-span');
const code = document.getElementById('pre-code');
const live = document.getElementById('live-announcer');
return !!h1 && !!link && !!btn && !!brand && !!code && !!live;

const isTranslated = document.documentElement.getAttribute('lang') === 'es';
if (!isTranslated) {
  return document.getElementById('main-title').textContent.includes('Welcome to the Community');
}
const h1 = document.getElementById('main-title');
const hero = document.getElementById('hero-tagline');
const bookTitle = document.getElementById('book-title');
const btn = document.getElementById('btn-reserve');
return h1.textContent === 'Bienvenidos a la Sala de Lectura Comunitaria' &&
       hero.textContent.includes('Descubra miles de libros') &&
       bookTitle.textContent === 'El arte del diseño accesible' &&
       btn.textContent === 'Reservar libro';

const isTranslated = document.documentElement.getAttribute('lang') === 'es';
const link = document.getElementById('author-link');
const desc = document.getElementById('book-desc');
if (!link || !desc) return false;
if (!isTranslated) {
  return link.getAttribute('href') === '#author-bio' && link.textContent === 'author biography';
}
const text = desc.textContent;
const keepsSpaces = text.includes('nuestra biografía del autor para más detalles');
const linkSurvives = link.tagName === 'A' &&
                     link.getAttribute('href') === '#author-bio' &&
                     link.textContent === 'biografía del autor';
return keepsSpaces && linkSurvives;

const pre = document.getElementById('pre-code');
const kbd = document.getElementById('search-kbd');
const samp = document.getElementById('sample-out');
const brand = document.getElementById('brand-span');
const corp = document.getElementById('corp-span');
const notes = document.getElementById('editable-notes');
const live = document.getElementById('live-announcer');
const alertBox = document.getElementById('alert-box');
return pre.textContent.includes('npm install @community/catalog-cli') &&
       kbd.textContent === 'Ctrl' &&
       samp.textContent === 'Loaded 42 titles successfully' &&
       brand.textContent === 'OpenCode Global' &&
       corp.textContent === 'CommunityBooks Ltd' &&
       notes.textContent.includes('Type your personal reading notes here.') &&
       live.textContent.includes('Current study desks available: 14 open desks.') &&
       alertBox.textContent.includes('Notice: The reading room closes at 9:00 PM tonight.');

const btn = document.getElementById('btn-reserve');
const link = document.getElementById('author-link');
const nav = document.getElementById('nav-catalog');
if (!btn || !link || !nav) return false;
btn.focus();
const btnFocused = document.activeElement === btn;
const btnRect = btn.getBoundingClientRect();
nav.focus();
const navFocused = document.activeElement === nav;
const navRect = nav.getBoundingClientRect();
btn.blur();
nav.blur();
return btnFocused && navFocused &&
       btnRect.width >= 24 && btnRect.height >= 24 &&
       navRect.width >= 24 && navRect.height >= 24;

const isTranslated = document.documentElement.getAttribute('lang') === 'es';
if (!isTranslated) return true;
const announced = globalThis.__verifyAnnounced || [];
const hasStart = announced.some(a => a.includes('Translating to Spanish'));
const hasDone = announced.some(a => a.includes('Translated') && a.includes('passages to Spanish'));
return hasStart && hasDone && document.documentElement.getAttribute('lang') === 'es';
